package com.resumeanalyzer.controller;
import com.resumeanalyzer.model.*;import com.resumeanalyzer.repository.*;import com.resumeanalyzer.service.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.security.Principal;import java.time.LocalDate;import java.io.IOException;
@Controller public class AppController {
 private final ResumeRepository resumes;private final LearningRepository learning;private final CalendarRepository events;private final NoteRepository notes;private final ResumeTextService extractor;private final AiAnalysisService ai;
 public AppController(ResumeRepository r,LearningRepository l,CalendarRepository e,NoteRepository n,ResumeTextService x,AiAnalysisService a){resumes=r;learning=l;events=e;notes=n;extractor=x;ai=a;}
 private void common(Model m,Principal p){m.addAttribute("email",p.getName());}
 @GetMapping("/")String home(Model m,Principal p){common(m,p);m.addAttribute("resumeCount",resumes.findByOwnerOrderByIdDesc(p.getName()).size());m.addAttribute("learningCount",learning.findByOwnerOrderByIdDesc(p.getName()).size());m.addAttribute("eventCount",events.findByOwnerOrderByEventDateAsc(p.getName()).size());m.addAttribute("noteCount",notes.findByOwnerOrderByIdDesc(p.getName()).size());m.addAttribute("events",events.findByOwnerOrderByEventDateAsc(p.getName()));return "dashboard";}
 @GetMapping("/resume")String resume(Model m,Principal p){common(m,p);m.addAttribute("resumes",resumes.findByOwnerOrderByIdDesc(p.getName()));return "resume";}
 @PostMapping("/resume/analyze")String analyze(@RequestParam("file")MultipartFile f,@RequestParam(defaultValue="")String jobDescription,Principal p)throws IOException{if(f.isEmpty())return "redirect:/resume?error=empty";String name=f.getOriginalFilename()==null?"resume":f.getOriginalFilename();if(!(name.toLowerCase().endsWith(".pdf")||name.toLowerCase().endsWith(".docx")))return "redirect:/resume?error=type";String txt=extractor.extract(f);if(txt.isBlank())return "redirect:/resume?error=emptytext";String out=ai.analyze(txt,jobDescription);ResumeRecord r=new ResumeRecord();r.setOwner(p.getName());r.setFileName(name);r.setJobTitle(jobDescription.length()>180?jobDescription.substring(0,180):jobDescription);r.setExtractedText(txt.substring(0,Math.min(10000,txt.length())));r.setAnalysis(out);r.setMatchScore(ai.score(out));resumes.save(r);return "redirect:/resume";}
 @GetMapping("/jobs")String jobs(Model m,Principal p){common(m,p);m.addAttribute("latest",resumes.findByOwnerOrderByIdDesc(p.getName()).stream().findFirst().orElse(null));return "jobs";}
 @GetMapping("/diary")String diary(Model m,Principal p){common(m,p);m.addAttribute("entries",learning.findByOwnerOrderByIdDesc(p.getName()));return "diary";}
 @PostMapping("/diary")String addDiary(@RequestParam String topic,@RequestParam(defaultValue="0")Double hours,@RequestParam String details,Principal p){LearningEntry e=new LearningEntry();e.setOwner(p.getName());e.setEntryDate(LocalDate.now());e.setTopic(topic);e.setHours(hours);e.setDetails(details);learning.save(e);return "redirect:/diary";}
 @GetMapping("/calendar")String calendar(Model m,Principal p){common(m,p);m.addAttribute("events",events.findByOwnerOrderByEventDateAsc(p.getName()));return "calendar";}
 @PostMapping("/calendar")String addEvent(@RequestParam String eventDate,@RequestParam String title,@RequestParam(defaultValue="")String description,@RequestParam(defaultValue="false")boolean reminder,Principal p){CalendarEvent e=new CalendarEvent();e.setOwner(p.getName());e.setEventDate(LocalDate.parse(eventDate));e.setTitle(title);e.setDescription(description);e.setReminder(reminder);events.save(e);return "redirect:/calendar";}
 @GetMapping("/notes")String notes(Model m,Principal p){common(m,p);m.addAttribute("notes",notes.findByOwnerOrderByIdDesc(p.getName()));return "notes";}
 @PostMapping("/notes")String addNote(@RequestParam String title,@RequestParam String content,Principal p){Note n=new Note();n.setOwner(p.getName());n.setTitle(title);n.setContent(content);notes.save(n);return "redirect:/notes";}
 @PostMapping("/notes/delete/{id}")String deleteNote(@PathVariable Long id,Principal p){notes.findById(id).filter(n->n.getOwner().equals(p.getName())).ifPresent(notes::delete);return "redirect:/notes";}
}
